<?php
declare(strict_types=1);require __DIR__.'/bootstrap_saas.php';require_once __DIR__.'/passenger_auth_helpers.php';
$db=saas_db();$me=passenger_require_login();$profileId=(int)$me['passenger_profile_id'];
$q=$db->prepare("SELECT tp.id,tp.status,tp.fee,tp.discount,t.id tour_id,t.name,t.slug,t.start_date,t.end_date,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.tour_passenger_id=tp.id AND p.tour_id=tp.tour_id),0) paid,ti.id ticket_id,ti.ticket_number FROM tour_passengers tp JOIN tours t ON t.id=tp.tour_id LEFT JOIN ticket_instances ti ON ti.tour_passenger_id=tp.id AND ti.status='ISSUED' AND ti.voided_at IS NULL WHERE tp.passenger_profile_id=? AND tp.status<>'CANCELLED' AND t.organization_id=? ORDER BY t.start_date DESC,tp.id DESC");$q->execute([$profileId,(int)$me['organization_id']]);$tours=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Tours</title><style>body{font-family:Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:950px;margin:30px auto;padding:16px}.top,.card{background:#fff;border-radius:16px;padding:20px;margin-bottom:16px;box-shadow:0 6px 24px #0000000b}.top{display:flex;justify-content:space-between;gap:15px;align-items:center}.muted{color:#667085;font-size:13px}.tour{border:1px solid #eaecf0;border-radius:12px;padding:15px;margin:10px 0}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:12px;font-weight:700}.actions a{display:inline-block;margin:8px 8px 0 0;padding:8px 11px;border:1px solid #d0d5dd;border-radius:8px;text-decoration:none;color:#172033;font-size:13px}.actions .primary{background:#155eef;color:#fff;border-color:#155eef}.actions .ticket{background:#067647;color:#fff;border-color:#067647}@media(max-width:650px){.top{display:block}}</style></head><body><main class="wrap"><section class="top"><div><h1>Welcome, <?=saas_h($me['full_name'])?></h1><div class="muted"><?=saas_h($me['email']??'')?> · <?=saas_h($me['phone']??'')?></div></div><div><a href="passenger_profile.php">My Profile</a> · <a href="passenger_dashboard.php?logout=1">Log out</a></div></section><section class="card"><h2>My Tours</h2><?php if(!$tours):?><p class="muted">No active tour bookings are linked to your account yet.</p><?php endif;?><?php foreach($tours as $t):$gross=max(0,(float)$t['fee']-(float)$t['discount']);$due=max(0,$gross-(float)$t['paid']);?><div class="tour"><strong><?=saas_h($t['name'])?></strong> <span class="pill"><?=saas_h($t['status'])?></span><div class="muted"><?=saas_h((string)$t['start_date'])?><?=($t['end_date']?' → '.saas_h((string)$t['end_date']):'')?></div><p>Paid: <?=number_format((float)$t['paid'],2)?> · Due: <?=number_format($due,2)?></p><div class="actions"><a class="primary" href="public_booking.php?tour_id=<?=$t['tour_id']?>&account=1">Manage Booking</a><a href="public_seat_select.php?tour_id=<?=$t['tour_id']?>&account=1">Seat</a><a href="public_room_select.php?tour_id=<?=$t['tour_id']?>&account=1">Room</a><?php if($due>0):?><a href="public_checkout.php?tour_id=<?=$t['tour_id']?>&account=1">Payment</a><?php endif;?><?php if($t['ticket_id']):?><a class="ticket" href="passenger_ticket.php?ticket_id=<?=$t['ticket_id']?>">Ticket · <?=saas_h($t['ticket_number'])?></a><?php endif;?></div></div><?php endforeach;?></section></main></body></html>